-- Mod-authored natural wonder portrait descriptions, it_IT overlay.
-- Baseline in CivVAccess_NaturalWonderDescStrings_en_US.lua.
CivVAccess_Strings = CivVAccess_Strings or {}

CivVAccess_Strings["TXT_KEY_CIVVACCESS_NWDESC_MISSING"] = "Nessuna descrizione per questa meraviglia naturale."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_NWDESC_FEATURE_CRATER"] =
    "Un vasto cratere da impatto visto dal suo orlo, una conca frastagliata scavata nel pallido suolo desertico. Il pendio vicino è coperto di macchia verde che precipita nella fossa in ombra, il cui fondo giace in una profonda oscurità bruna, e l'orlo lontano si innalza in fasce di marrone chiaro e oro sotto un cielo velato."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_NWDESC_FEATURE_EL_DORADO"] =
    "Una piramide a gradoni d'oro massiccio, con una ripida scalinata che ne risale la facciata fino a un piccolo santuario in cima. Giganteschi lingotti d'oro sono accatastati alla sua base tra esili alberi scuri, e l'intera scena risplende di giallo, il tesoro della mitica città reso letterale. I raggi di luce dietro di essa sembrano un'alba che irrompe sopra la città perduta."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_NWDESC_FEATURE_FOUNTAIN_YOUTH"] =
    "Una sorgente d'acqua turchese di una luminosità impossibile sgorga da una vasca in cima a scure scogliere rocciose e si riversa in basso come una cascata splendente nello specchio d'acqua sottostante. Ciuffi d'erba verde si aggrappano alla roccia nera, fronde di palma incorniciano un caldo cielo dorato, e minuscoli bagliori nell'acqua la rivelano magica più che naturale."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_NWDESC_FEATURE_FUJI"] =
    "Un perfetto cono vulcanico riempie l'inquadratura, la sua ampia calotta nevosa che scende lungo i pendii per quasi tutta la loro estensione. La neve è dipinta in bianco tenue e azzurro pallido contro un cielo blu intenso, e una striscia di verde sterpaglia e acqua nebbiosa giace lungo il piede della montagna."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_NWDESC_FEATURE_GEYSER"] =
    "Un geyser erutta da un pallido cumulo roccioso, il suo spruzzo bianco che si apre a ventaglio fino a riempire l'intero cielo di foschia contro il blu. Una scura foresta di sempreverdi si stringe su entrambi i lati, e in primo piano si stende una crosta di terrazze minerali in marrone chiaro, ocra e bruno."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_NWDESC_FEATURE_GIBRALTAR"] =
    "Un grande promontorio calcareo si erge da un mare piatto, con scogliere pallide e a strapiombo sulla sua faccia sinistra e un lungo pendio di scura vegetazione verde che ne scende lungo il dorso. L'intera scena è immersa nell'oro, il cielo e l'acqua che risplendono come nel tardo pomeriggio."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_NWDESC_FEATURE_KILIMANJARO"] =
    "Un'enorme cupola striata di neve riempie la metà superiore dell'inquadratura in bianco gelido e blu, con un anello di piccole nubi che fluttua alla sua base. Sotto di essa si estende una verde savana dove due giraffe sostano presso una pallida pozza d'acqua, con alberi dalla chioma piatta ai bordi della scena."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_NWDESC_FEATURE_LAKE_VICTORIA"] =
    "Un ampio lago turchese si distende fino a pallide colline all'orizzonte, racchiuso da rocciosi affioramenti color marrone chiaro su entrambi i lati. Al centro, in primo piano, un ippopotamo affiora, la testa e il dorso che rompono l'acqua increspata, sotto un bianco bagliore di luce che riempie il cielo."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_NWDESC_FEATURE_MESA"] =
    "Una mesa dalla cima piatta, di roccia stratificata rosso-arancio, si erge solitaria da una pianura arida, con pareti rocciose a fasce sopra lunghi pendii di roccia franata. Rada macchia verde punteggia il terreno sabbioso ai suoi piedi, e la sommità piatta taglia una linea netta contro un cielo azzurro brillante."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_NWDESC_FEATURE_MT_KAILASH"] =
    "Una piramide di roccia a fasce e neve si erge contro un cielo blu intenso, la sua faccia striata illuminata di oro caldo su un lato. Sotto di essa il primo piano è tutto ruvido nevaio e creste di ghiaccio in fredda ombra azzurra."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_NWDESC_FEATURE_MT_SINAI"] =
    "Un gruppo di vette desertiche frastagliate in arenaria bruno-arancio, profonde gole che ne solcano le facce, con un tenue bagliore di luce che spunta da dietro la sommità centrale. Massi sparsi disseminano il pianoro sabbioso in primo piano sotto un cielo azzurro terso."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_NWDESC_FEATURE_POTOSI"] =
    "Una nuda montagna bruno-rossastra i cui pendii inferiori sono sepolti sotto cumuli di massi grigi luccicanti di minerale d'argento. Un sentiero serpeggia su per il suo fianco, file di scuri blocchi squadrati ne fiancheggiano la base come scavi minerari, e la sommità polverosa si staglia contro un cielo blu."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_NWDESC_FEATURE_REEF"] =
    "Una scena subacquea: il corallo si affolla a sinistra e in basso nell'inquadratura in arancione, rosso, viola e azzurro pallido, con spugne a tubo che svettano erette tra i rami. Piccoli pesci tropicali vagano nell'acqua blu profonda, uno di un giallo brillante al centro. La luce sfuma in un'aperta oscurità verso l'alto a destra."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_NWDESC_FEATURE_SOLOMONS_MINES"] =
    "Un monumentale corpo di guardia che sta per le leggendarie miniere: un'alta e scura muraglia di fortezza coronata da merli con punte dorate, una porta al suo centro, fiancheggiata da torri di pietra color marrone chiaro. Davanti a essa il pallido suolo roccioso è scolpito in ampie curve sinuose, come se il terreno stesso fosse stato cavato fino a renderlo liscio."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_NWDESC_FEATURE_SRI_PADA"] =
    "Una rigogliosa montagna verde si innalza fino a una vetta arrotondata, la giungla che ne ricopre i pendii salvo dove la roccia bruno-arancio affiora in scogliere. Alti fili d'erba con piccoli fiori azzurri riempiono il primo piano, e il cielo dietro è di un vivido turchese tropicale."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_NWDESC_FEATURE_ULURU"] =
    "Un grande monolito rosso si distende nella media distanza, la sua massa arrotondata di arenaria solcata da scanalature verticali e splendente d'arancio nella luce. Davanti a esso si stende la piatta sterpaglia dell'entroterra, terra rossa chiazzata di bassa macchia verde e ciuffi d'erba, sotto un cielo azzurro brillante."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_NWDESC_FEATURE_VOLCANO"] =
    "Uno scuro cono vulcanico si erge dal mare oltre una striscia di pallida acqua turchese, visto da una riva di giungla le cui larghe foglie verdi incorniciano la scena. Il cielo sopra di esso arde di un giallo sulfureo, con un debole ricciolo di fumo sopra la sommità che lascia presagire l'eruzione imminente."
